import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

import '../firebase_options.dart';
import 'firebase_push_service.dart';
import 'push_service.dart';
import 'stub_push_service.dart';

/// Initialises Firebase when `lib/firebase_options.dart` has been generated by `flutterfire configure`;
/// otherwise (the committed stub throws UnsupportedError) falls back to [StubPushService].
Future<PushService> initPush(SharedPreferences prefs) async {
  final FirebaseOptions options;
  try {
    options = DefaultFirebaseOptions.currentPlatform;
  } on UnsupportedError catch (e) {
    debugPrint('$e');
    return StubPushService(prefs);
  }
  try {
    await Firebase.initializeApp(options: options);
    return await FirebasePushService.create();
  } catch (e) {
    debugPrint('Firebase initialisation failed, falling back to StubPushService: $e');
    return StubPushService(prefs);
  }
}
